/**
 * Base64url and random-byte helpers for the provisional device identity.
 *
 * These are encoding helpers only; secret material is generated by Web Crypto
 * (`crypto.getRandomValues` / `crypto.subtle.generateKey`). No custom
 * cryptographic algorithm is implemented here.
 */

export function base64UrlEncode(input: ArrayBuffer | Uint8Array): string {
  const bytes = input instanceof Uint8Array ? input : new Uint8Array(input);
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return globalThis.btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

export function base64UrlDecode(value: string): Uint8Array {
  if (!/^[A-Za-z0-9_-]+$/.test(value)) {
    throw new Error("Invalid base64url value.");
  }
  const padded = value.replace(/-/g, "+").replace(/_/g, "/");
  const withPadding = padded + "=".repeat((4 - (padded.length % 4)) % 4);
  const binary = globalThis.atob(withPadding);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

export function randomBytes(length: number): Uint8Array {
  if (!Number.isInteger(length) || length < 1) {
    throw new Error("randomBytes requires a positive integer length.");
  }
  const bytes = new Uint8Array(length);
  globalThis.crypto.getRandomValues(bytes);
  return bytes;
}

/** Opaque 128-bit device reference; matches the shared DEVICE_ID_RE. */
export function newDeviceId(): string {
  return base64UrlEncode(randomBytes(16));
}

/** Opaque 72-bit key identifier scoped to one device bundle. */
export function newKeyId(): string {
  return base64UrlEncode(randomBytes(9));
}
